class PlotRow extends DataClass implements Insertable<PlotRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final String? updatedBy;
  final bool isDeleted;
  final DateTime? deletedAt;
  final String? deletedBy;

  /// 乐观锁版本号。C# 侧为 EF 行版本的 `byte[] Version`，
  /// Dart 侧改为整数，由 Repository 层在更新时自增。
  final int version;
  final String title;

  /// 主线 / 支线 / 暗线 / 伏笔
  final String type;

  /// 规划中 / 进行中 / 已完成 / 暂停
  final String status;

  /// 高 / 中 / 低
  final String priority;

  /// 进度百分比，C# 为 decimal
  final double progress;

  /// 起始章节。Chapter↔Plot 共 3 条关系之一，两条外键需要不同 @ReferenceName
  /// 以免 manager 生成的反向引用重名
  final String? startChapterId;
  final String? endChapterId;
  final String? description;
  final String? outline;
  final String? conflictElements;
  final String? themeElements;
  final String projectId;
  final int importance;
  final String? tags;
  final String? notes;
  final int? estimatedWordCount;
  final int actualWordCount;
  const PlotRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.createdBy,
    this.updatedBy,
    required this.isDeleted,
    this.deletedAt,
    this.deletedBy,
    required this.version,
    required this.title,
    required this.type,
    required this.status,
    required this.priority,
    required this.progress,
    this.startChapterId,
    this.endChapterId,
    this.description,
    this.outline,
    this.conflictElements,
    this.themeElements,
    required this.projectId,
    required this.importance,
    this.tags,
    this.notes,
    this.estimatedWordCount,
    required this.actualWordCount,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
