      map['deleted_by'] = Variable<String>(deletedBy);
    }
    map['version'] = Variable<int>(version);
    map['title'] = Variable<String>(title);
    map['type'] = Variable<String>(type);
    map['status'] = Variable<String>(status);
    map['priority'] = Variable<String>(priority);
    map['progress'] = Variable<double>(progress);
    if (!nullToAbsent || startChapterId != null) {
      map['start_chapter_id'] = Variable<String>(startChapterId);
    }
    if (!nullToAbsent || endChapterId != null) {
      map['end_chapter_id'] = Variable<String>(endChapterId);
