class ResourceRow extends DataClass implements Insertable<ResourceRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final String? updatedBy;
  final bool isDeleted;
  final DateTime? deletedAt;
  final String? deletedBy;

  /// 乐观锁版本号。C# 侧为 EF 行版本的 `byte[] Version`，
  /// Dart 侧改为整数，由 Repository 层在更新时自增。
  final int version;
  final String name;

  /// 矿脉 / 灵脉 / 龙脉 / 草药 / 灵兽 / 水源 / 人口 / 装备 / 灵宝
  final String type;
  final String? location;

  /// 控制势力，势力删除置空
  final String? controllingFactionId;

  /// 普通 / 不常见 / 稀有 / 史诗 / 传说
  final String rarity;
  final int extractionDifficulty;
  final int economicValue;

  /// 极慢 / 缓慢 / 中等 / 快速 / 极快
  final String regenerationSpeed;

  /// 活跃 / 濒临枯竭 / 枯竭 / 废弃 / 受保护 / 争夺中
  final String status;
  final String? description;
  final String? extractionMethod;
  final String projectId;
  final int importance;
  final String? tags;
  final String? notes;

  /// 以下三个储量字段 C# 为 long?
  final int? currentReserves;
  final int? maxReserves;
  final int? annualOutput;
  final DateTime? discoveryDate;
  final DateTime? lastExtractionDate;
  const ResourceRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.createdBy,
    this.updatedBy,
