    this.location,
    this.controllingFactionId,
    required this.rarity,
    required this.extractionDifficulty,
    required this.economicValue,
    required this.regenerationSpeed,
    required this.status,
    this.description,
    this.extractionMethod,
    required this.projectId,
    required this.importance,
    this.tags,
    this.notes,
    this.currentReserves,
    this.maxReserves,
    this.annualOutput,
    this.discoveryDate,
    this.lastExtractionDate,
  });
