class CharacterRow extends DataClass implements Insertable<CharacterRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String? createdBy;
  final String? updatedBy;
  final bool isDeleted;
  final DateTime? deletedAt;
  final String? deletedBy;

  /// 乐观锁版本号。C# 侧为 EF 行版本的 `byte[] Version`，
  /// Dart 侧改为整数，由 Repository 层在更新时自增。
  final int version;
  final String name;
  final String type;
  final String? gender;
  final int? age;
  final String? cultivationLevel;

  /// 所属势力，势力删除时置空（对齐 C# 的 SetNull）
  final String? factionId;

  /// 所属种族，种族删除时置空
  final String? raceId;
  final int importance;
  final String? appearance;
  final String? personality;
  final String? background;
  final String? abilities;

  /// 所属项目，删除项目级联删除角色
  final String projectId;
  final String? avatarPath;
  final String? tags;
  final String? notes;
  final String status;

  /// 首次/最后出场章节。C# 中为无外键约束的裸 Guid，此处保留弱引用语义
  final String? firstAppearanceChapterId;
  final String? lastAppearanceChapterId;
  final String? history;
  final String? keyEvents;
